<script setup>
import {onMounted,ref,computed,watch} from 'vue';
import {api} from '../services/api.js';
import StatCard from '../components/StatCard.vue';import FilterBar from '../components/FilterBar.vue';import DataTable from '../components/DataTable.vue';
import {WalletCards,CarFront,ReceiptText,UsersRound,Download,RefreshCw} from 'lucide-vue-next';
const props=defineProps({role:{type:String,default:'admin'}});
const filters=ref({from:'',to:'',period_id:'',driver_id:'',vehicle_type:'',status:'',booking_status:''});
const report=ref(null),drivers=ref([]),periods=ref([]),loading=ref(false),error=ref('');const tab=ref('settlements');
const money=n=>Number(n||0).toLocaleString('vi-VN')+' ₫';
const format=(v,k)=>['gross_revenue','app_fee','wallet_return','amount','fare','promo','insurance_fee','tips','receivable','paid'].includes(k)?money(v):(v??'—');
const filterFields=computed(()=>[{key:'from',label:'Từ ngày',type:'date'},{key:'to',label:'Đến ngày',type:'date'},{key:'period_id',label:'Kỳ đối soát',options:periods.value.map(x=>({value:x.id,label:x.name}))},{key:'driver_id',label:'Tài xế',options:drivers.value.map(x=>({value:x.id,label:x.full_name}))},{key:'vehicle_type',label:'Loại xe',options:[{value:'car',label:'Ô tô'},{value:'motorbike',label:'Xe máy'}]},{key:'status',label:'Tình trạng thu',options:[{value:'pending',label:'Chưa thu'},{value:'paid',label:'Đã thu'},{value:'none',label:'Không thu'}]},{key:'booking_status',label:'Trạng thái chuyến',options:[{value:'pending',label:'Chờ xác nhận'},{value:'accepted',label:'Đã nhận'},{value:'completed',label:'Hoàn tất'},{value:'rejected',label:'Từ chối'},{value:'cancelled',label:'Đã hủy'}]}]);
const tabs=[{id:'settlements',name:'Phiếu đối soát',cols:[['period_name','Kỳ'],['driver_name','Tài xế'],['plate','Biển số'],['gross_revenue','Doanh thu'],['app_fee','Phí ứng dụng'],['wallet_return','Hoàn ví'],['collection_status','Trạng thái']]},{id:'bookings',name:'Chi tiết chuyến',cols:[['code','Mã chuyến'],['driver_name','Tài xế'],['customer_name','Khách hàng'],['departure_at','Khởi hành'],['fare','Cước'],['status','Trạng thái']]},{id:'byDriver',name:'Tổng hợp tài xế',cols:[['driver_name','Tài xế'],['phone','SĐT'],['periods','Số kỳ'],['gross_revenue','Doanh thu'],['app_fee','Phí app'],['wallet_return','Hoàn ví']]},{id:'byPeriod',name:'Tổng hợp kỳ',cols:[['period_name','Kỳ'],['records','Số phiếu'],['gross_revenue','Doanh thu'],['app_fee','Phí app'],['wallet_return','Hoàn ví']]},{id:'ledger',name:'Công nợ',cols:[['entry_type','Loại'],['driver_id','Mã tài xế'],['amount','Số tiền'],['note','Nội dung'],['created_at','Ngày']]}];
const currentTab=computed(()=>tabs.find(x=>x.id===tab.value));const rows=computed(()=>report.value?.[tab.value]||[]);
async function load(){loading.value=true;error.value='';try{const q=new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v)).toString();report.value=await api('/reports?'+q)}catch(e){error.value=e.message}finally{loading.value=false}}
async function initial(){try{if(props.role!=='driver'){[drivers.value,periods.value]=await Promise.all([api('/drivers'),api('/periods')])}}catch(e){error.value=e.message}await load()}
let seq=0;watch(filters,()=>{const id=++seq;Promise.resolve().then(()=>{if(seq===id)load()})},{deep:true});onMounted(initial);
const csvCell=x=>'"'+String(x??'').replaceAll('"','""')+'"';
function exportCSV(){const cols=currentTab.value.cols;const lines=[cols.map(x=>csvCell(x[1])).join(','),...rows.value.map(row=>cols.map(x=>csvCell(row[x[0]])).join(','))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`bao-cao-${tab.value}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="report-view"><div class="panel report-filter"><div class="panel-head"><h3>Bộ lọc báo cáo</h3><span>Dữ liệu được tính trên các bản ghi phù hợp</span></div><FilterBar v-model="filters" :fields="filterFields" @reset="filters={from:'',to:'',period_id:'',driver_id:'',vehicle_type:'',status:'',booking_status:''}"/></div><div v-if="error" class="alert">{{error}}</div><div v-if="loading" class="subtle">Đang tổng hợp báo cáo…</div><div class="stats" v-if="report"><StatCard label="Tổng chuyến" :value="report.summary.trips" :icon="CarFront" :sub="`${report.summary.completed} chuyến hoàn tất`"/><StatCard label="Doanh thu đối soát" :value="money(report.summary.revenue)" :icon="WalletCards"/><StatCard label="Phí ứng dụng" :value="money(report.summary.app_fee)" :icon="ReceiptText"/><StatCard label="Tài xế có chuyến" :value="report.summary.drivers" :icon="UsersRound"/></div><div v-if="report" class="report-extras"><div class="panel"><h3>Chi tiết dòng tiền</h3><div v-for="[name,key] in [['Khuyến mãi','promo'],['Bảo hiểm','insurance_fee'],['Tiền tip','tips'],['Hoàn ví','wallet_return'],['Truy thu phát sinh','receivable'],['Thanh toán ghi nhận','paid']]" :key="key" class="finance-line"><span>{{name}}</span><b>{{money(report.summary[key])}}</b></div></div><div class="panel"><h3>Trạng thái chuyến</h3><div v-for="x in report.statusCounts" :key="x.status" class="barrow"><span>{{x.status}}</span><div class="bartrack"><div class="barfill" :style="{width:100*x.count/Math.max(1,report.summary.trips)+'%'}"></div></div><b>{{x.count}}</b></div><div v-if="!report.statusCounts.length" class="empty">Chưa có dữ liệu</div></div></div><div class="panel table-panel"><div class="table-head report-table-head"><div><h3>Bảng báo cáo chi tiết</h3><span>{{rows.length}} dòng theo điều kiện đã chọn</span></div><div class="head-actions"><button class="secondary" @click="load"><RefreshCw :size="15"/> Làm mới</button><button class="primary" @click="exportCSV" :disabled="!rows.length"><Download :size="15"/> Xuất CSV</button></div></div><div class="report-tabs"><button v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="tab=t.id">{{t.name}}</button></div><DataTable :rows="rows" :columns="currentTab.cols" :formatter="format" :page-size="12"/></div></div></template>
